script:
html { scroll-behavior: smooth; }
::selection { background: #FF6A2B; color: #F5F4EF; }
.dn-ticker-track { animation: dn-marquee 22s linear infinite; }
@keyframes dn-marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@media (prefers-reduced-motion: reduce) { .dn-ticker-track { animation: none; } }
